<?php
declare(strict_types=1);
// Provider lists (docs/workspaces.md#provider-lists): a ProviderResource reads, filters, sorts, numbers, pages and
// observes like an SQL list over the same rows; ACL, validation and record reads follow the ordinary rules.
require dirname(__DIR__,2).'/examples/demo-app/vendor/autoload.php';
use Blade\Feature\{Action,Context,Failure,Field,ListProvider,ListQuery,ProviderResource,Registry,SqlResource,Workspace};
use Blade\Shell\Identity;
function verify(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
function status(callable $run):int{try{$run();return 200;}catch(Failure $e){return $e->status;}}

$db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);Blade\Access\Schema::install($db);
$fields=fn()=>[new Field('name','Name'),new Field('state','State','select',options:['ok'=>'OK','warn'=>'Warning','down'=>'Down'],column:['tones'=>['warn'=>'warning','down'=>'danger']]),
    new Field('load','Load','number'),new Field('site','Site'),new Field('active','Active','checkbox'),new Field('notes','Notes','textarea')];
// The same 250 rows as an SQL table and as provider rows: lower-case text (SQLite compares bytes), nulls in `load`, nulls and
// empty strings in `site`.
$rows=[];for($i=1;$i<=250;$i++)$rows[]=['host'=>(string)$i,'name'=>'host-'.str_pad((string)(($i*37)%250),3,'0',STR_PAD_LEFT),'state'=>['ok','warn','down'][$i%3],'load'=>$i%7===0?null:($i*13)%50,'site'=>$i%11===0?null:($i%13===0?'':'site '.chr(97+$i%4)),'active'=>$i%2===0,'notes'=>'n'.$i];
$db->exec('CREATE TABLE hosts (host INTEGER PRIMARY KEY, name TEXT, state TEXT, load INTEGER, site TEXT, active TEXT, notes TEXT)');
$insert=$db->prepare('INSERT INTO hosts VALUES (?,?,?,?,?,?,?)');foreach($rows as $r)$insert->execute([(int)$r['host'],$r['name'],$r['state'],$r['load'],$r['site'],$r['active']?'1':'0',$r['notes']]);

/** A windowed provider over the same rows (ListQuery's own rules, one window by offset). */
final class Hosts implements ListProvider
{
    public int $calls=0;
    public function __construct(private array $rows){}
    public function rows(Context $ctx,ListQuery $query):array{$this->calls++;$matched=$query->apply($this->rows);return ['rows'=>array_slice($matched,$query->offset,$query->limit),'total'=>count($this->rows),'matched'=>count($matched),'notice'=>['text'=>'Generated by the test','tone'=>'warning']];}
    public function row(Context $ctx,string $key):?array{foreach($this->rows as $row)if($row['host']===$key)return $row;return null;}
}
$registry=new Registry();
(new SqlResource('sql_hosts','hosts','host',$fields(),search:['name','site']))->register($registry,'SQL hosts',create:false,update:false);
$closure=new ProviderResource('hosts','host',$fields(),fn(Context $c)=>['rows'=>$rows,'notice'=>['text'=>'Report of 250 hosts']],search:['name','site']);
$closure->register($registry,'Hosts',sort:['field'=>'name','direction'=>'asc']);
$windowed=new Hosts($rows);(new ProviderResource('paged_hosts','host',$fields(),$windowed,search:['name','site']))->register($registry,'Paged hosts');
// A consumer's own record action resolves the row through target().
$registry->add(new Action('hosts','restart','Restart',[],fn(Context $c,array $t)=>['restarted'=>$t['row']['name']],resolve:fn($c,$id)=>$closure->target($c,$id),write:true));
$registry->appendViewActions('hosts',['restart']);
$w=new Workspace($registry,$db);$ctx=new Context(new Identity('1','One'),'ui',$w->acl,$db);
$rule=$db->prepare("INSERT INTO blade_rules(subject_type,subject_id,resource,action,channel,effect,scope,object_id,field_name) VALUES ('user','1',?,?,'ui',?,?,?,?)");
foreach(['sql_hosts','hosts','paged_hosts'] as $resource)foreach(['list','get'] as $action)$rule->execute([$resource,$action,'allow','all','','']);
$rule->execute(['hosts','restart','allow','all','','']);
$read=fn(string $resource,array $values)=>$w->executor->execute($ctx,$resource,'list',null,$values);
$ids=fn(array $result)=>array_column($result['items'],'id');
$shape=fn(array $result)=>[$ids($result),$result['total'],$result['matched'],array_column($result['items'],'_number'),$result['previous']!==null,$result['next']!==null];

// Parity with the SQL list: every query, sort and page in both directions.
$queries=[[],['filters'=>['state'=>'warn']],['filters'=>['site'=>'B']],['filters'=>['load'=>'26']],['filters'=>['active'=>'1','state'=>'down']],['search'=>'HOST-01'],['search'=>'site c','filters'=>['state'=>'ok']],['scope'=>['field'=>'site','value'=>'site d']],['scope'=>['field'=>'site','value'=>'']],['filters'=>['site'=>'']],['search'=>'site'],['filters'=>['name'=>'zzz']]];
$sorts=[null,['field'=>'id','direction'=>'asc'],['field'=>'name','direction'=>'desc'],['field'=>'load','direction'=>'asc'],['field'=>'load','direction'=>'desc'],['field'=>'state','direction'=>'asc'],['field'=>'active','direction'=>'desc']];
foreach($queries as $query)foreach($sorts as $sort)foreach(['hosts','paged_hosts'] as $resource){
    $values=[...$query,'limit'=>40,...($sort?['sort'=>$sort]:[])];
    $sql=$read('sql_hosts',$values);$provider=$read($resource,$values);$label=$resource.' '.json_encode($values);
    verify($shape($provider)===$shape($sql),'First page as the SQL list: '.$label);
    for($page=0;$sql['next']&&$page<8;$page++){
        $sql=$read('sql_hosts',[...$values,'cursor'=>$sql['next']]);$provider=$read($resource,[...$values,'cursor'=>$provider['next']]);
        verify($ids($provider)===$ids($sql)&&array_column($provider['items'],'_number')===array_column($sql['items'],'_number'),'Next page as the SQL list: '.$label);
    }
    if($sql['previous']){
        $back=$read('sql_hosts',[...$values,'cursor'=>$sql['previous']]);$providerBack=$read($resource,[...$values,'cursor'=>$provider['previous']]);
        verify($ids($providerBack)===$ids($back)&&array_column($providerBack['items'],'_number')===array_column($back['items'],'_number'),'Previous page as the SQL list: '.$label);
    }
}
verify($read('hosts',[])['notice']===['text'=>'Report of 250 hosts','tone'=>'info']&&$read('paged_hosts',[])['notice']['tone']==='warning'&&!isset($read('sql_hosts',[])['notice']),'A provider notice reaches the list answer');
$first=$read('hosts',['limit'=>5]);$item=$first['items'][0];
verify(array_keys($item)===['id','revision','name','state','load','site','active','notes','_actions','_editable','_position','_number']&&$item['active']===ListQuery::text($rows[(int)$item['id']-1]['active'])&&$item['_actions']===['list','get','restart'],'Provider rows are projected like SQL rows');
verify($first['items'][0]['name']<=$first['items'][1]['name'],'The declared first sort is the view\'s, the default read sorts by key');

// Live observation and records: the same channel and get action as an SQL list.
$live=$w->observe($ctx,'hosts',['limit'=>100,'front'=>true]);verify(count($live['items'])===100&&isset($live['version']),'A provider list is observed');
verify(($w->observe($ctx,'hosts',['limit'=>100,'front'=>true],$live['version'])['unchanged']??false)===true,'An unchanged provider window answers its version only');
$anchor=$read('hosts',['limit'=>10,'sort'=>['field'=>'load','direction'=>'desc']]);$tenth=$anchor['items'][9];
$from=fn($resource,$row)=>$w->observe($ctx,$resource,['limit'=>5,'front'=>false,'first'=>$row['id'],'sort'=>['field'=>'load','direction'=>'desc'],'anchor'=>rtrim(strtr(base64_encode(json_encode([...$row['_position'],'edge'=>$row['id'],'direction'=>'next'])),'+/','-_'),'=')]);
verify($from('hosts',$tenth)['items'][0]['id']===$tenth['id'],'A watch window starts at its anchor record');
$pagedTenth=$read('paged_hosts',['limit'=>10,'sort'=>['field'=>'load','direction'=>'desc']])['items'][9];
verify($ids($from('paged_hosts',$pagedTenth))===$ids($from('hosts',$tenth)),'A windowed provider\'s watch window starts at its anchor offset');
$record=$w->executor->execute($ctx,'hosts','get','42',[]);verify($record['id']==='42'&&$record['name']===$rows[41]['name'],'get reads one row by key');
verify($w->observe($ctx,'paged_hosts',['record'=>'42'])['items'][0]['name']===$rows[41]['name'],'A record watch reads a provider row');
verify(status(fn()=>$w->executor->execute($ctx,'hosts','get','999',[]))===404&&status(fn()=>$w->executor->execute($ctx,'hosts','get','bad key',[]))===404,'An unknown key is not found');
verify($w->executor->execute($ctx,'hosts','restart','7',[])['restarted']===$rows[6]['name'],'A consumer action reaches the provider row');

// Validation is the SQL list's: the same refusals for the same input.
foreach([['filters'=>['notes'=>'n1']],['filters'=>['state'=>'nope']],['filters'=>['load'=>'1.5']],['sort'=>['field'=>'notes','direction'=>'asc']],['mode'=>'later'],['limit'=>201],['cursor'=>'x'],['page'=>1],['filters'=>['unknown'=>'1']]] as $bad)
    foreach(['hosts','paged_hosts'] as $resource)verify(status(fn()=>$read($resource,$bad))===status(fn()=>$read('sql_hosts',$bad))&&status(fn()=>$read($resource,$bad))!==200,'Refused like the SQL list: '.json_encode($bad));
$sqlCursor=$read('sql_hosts',['limit'=>5,'sort'=>['field'=>'name','direction'=>'asc']])['next'];
verify(status(fn()=>$read('hosts',['limit'=>5,'cursor'=>$sqlCursor]))===400,'A cursor of another sort is refused');
verify(status(fn()=>$read('paged_hosts',['limit'=>5,'cursor'=>$read('hosts',['limit'=>5])['next']]))===400,'A windowed provider needs its own offset cursor');

// Views: the standard list metadata (filters, sort, search, tones) and the declared actions.
$view=array_column($w->views(new Identity('1','One')),null,'id')['hosts'];
verify(array_column($view['options']['filters'],'name')===['name','state','load','site','active']&&in_array('load',$view['options']['sortable'],true)&&$view['options']['search']===['fields'=>['name','site']],'A provider view offers the standard filters, sort and search');
verify(($view['options']['columns'][1]['tones']??null)==(object)['warn'=>'warning','down'=>'danger']&&$view['options']['sort']===['field'=>'name','direction'=>'asc']&&array_column($view['actions'],'name')===['get','restart'],'A provider view carries the field metadata and its actions');

// ACL: rows by the object rules (closure form), the field ACL of every value, a windowed read only for unrestricted actors.
$db->exec("DELETE FROM blade_rules WHERE resource IN ('hosts','paged_hosts') AND action='list'");$w->acl->invalidate();
verify($read('hosts',[])['items']===[]&&$read('hosts',[])['total']===0&&$read('paged_hosts',[])['items']===[],'Without a list allow nothing is listed');
$rule->execute(['hosts','list','allow','id','12','']);$rule->execute(['hosts','list','allow','id','13','']);$w->acl->invalidate();
verify($ids($read('hosts',[]))===['13','12']&&$read('hosts',[])['total']===2,'Id-scoped list rules list those rows only');
$rule->execute(['paged_hosts','list','allow','id','12','']);$w->acl->invalidate();
verify(status(fn()=>$read('paged_hosts',[]))===403,'A windowed provider refuses a record-limited list permission');
$rule->execute(['hosts','list','allow','all','','']);$rule->execute(['hosts','list','deny','id','12','']);$rule->execute(['hosts','list','deny','all','','notes']);$w->acl->invalidate();
$listed=$read('hosts',['limit'=>200]);
verify(!in_array('12',$ids($listed),true)&&$listed['total']===249&&!array_key_exists('notes',$listed['items'][0]),'A deny hides its row, a field deny its value');
$rule->execute(['hosts','list','deny','all','','load']);$w->acl->invalidate();
verify(status(fn()=>$read('hosts',['filters'=>['load'=>'1']]))===403&&status(fn()=>$read('hosts',['sort'=>['field'=>'load','direction'=>'asc']]))===403,'A field the actor may not read is neither filtered nor sorted');
$rule->execute(['hosts','get','deny','id','42','']);$w->acl->invalidate();
verify(status(fn()=>$w->executor->execute($ctx,'hosts','get','42',[]))===403&&status(fn()=>$w->executor->execute(new Context(new Identity('2','Two'),'ui',$w->acl,$db),'hosts','get','41',[]))===403,'get is checked on the server per record');

// Keys of mixed kinds page completely in both directions (digit-only keys first, then the others).
$mixed=new Registry();$keys=[...array_map('strval',range(1,40)),...array_map(static fn($i)=>$i.'a',range(1,40))];
(new ProviderResource('mixed','k',[new Field('name','Name')],fn()=>array_map(static fn($k)=>['k'=>$k,'name'=>'x'],$keys)))->register($mixed,'Mixed');
$mw=new Workspace($mixed,$db);$mctx=new Context(new Identity('1','One'),'ui',$mw->acl,$db);$rule->execute(['mixed','list','allow','all','','']);$mw->acl->invalidate();
foreach(['asc','desc'] as $direction){
    $seen=[];$page=$mw->executor->execute($mctx,'mixed','list',null,['limit'=>7,'sort'=>['field'=>'id','direction'=>$direction]]);$pages=[$page];
    for($n=0;$page['next']&&$n<20;$n++)$pages[]=$page=$mw->executor->execute($mctx,'mixed','list',null,['limit'=>7,'sort'=>['field'=>'id','direction'=>$direction],'cursor'=>$page['next']]);
    foreach($pages as $one)foreach($one['items'] as $item)$seen[]=$item['id'];
    verify(count($seen)===80&&count(array_unique($seen))===80&&($direction==='asc'?$seen[0]==='1'&&$seen[40]==='10a':$seen[0]==='9a'&&$seen[79]==='1'),'Mixed keys page completely: '.$direction);
    $back=$mw->executor->execute($mctx,'mixed','list',null,['limit'=>7,'sort'=>['field'=>'id','direction'=>$direction],'cursor'=>$pages[3]['previous']]);
    verify(array_column($back['items'],'id')===array_column($pages[2]['items'],'id'),'Mixed keys page back: '.$direction);
}
// The revision hashes only the values the actor may read (no hidden value can be guessed from it).
$hidden=$read('hosts',['limit'=>1,'filters'=>['name'=>$rows[40]['name']]])['items'][0];
$rule->execute(['hosts','list','allow','all','','notes']);$w->acl->invalidate();
verify(!array_key_exists('notes',$hidden)&&$hidden['revision']===hash('sha256',json_encode([$hidden['id'],array_diff_key($hidden,array_flip(['id','revision','_actions','_editable','_position','_number']))])),'The revision covers the visible values only');

// Developer errors (the executor logs them and answers 500): keys, values, notices and declarations.
ini_set('error_log','/dev/null');
$broken=function(array|Closure $rows,string $message)use($fields,$db):void{
    $registry=new Registry();(new ProviderResource('broken','host',$fields(),is_array($rows)?fn()=>$rows:$rows))->register($registry,'Broken');
    $w=new Workspace($registry,$db);$ctx=new Context(new Identity('1','One'),'ui',$w->acl,$db);
    $db->exec("INSERT INTO blade_rules(subject_type,subject_id,resource,action,channel,effect,scope,object_id,field_name) VALUES ('user','1','broken','list','ui','allow','all','','')");$w->acl->invalidate();
    verify(status(fn()=>$w->executor->execute($ctx,'broken','list',null,[]))===500,$message);
};
$broken([['host'=>'1'],['host'=>'1']],'Duplicate keys accepted');
$broken([['host'=>'a b']],'An invalid key accepted');
$broken([['host'=>'1','name'=>['x']]],'A non-scalar value accepted');
$broken(fn()=>['rows'=>[],'notice'=>['text'=>str_repeat('x',301)]],'A long notice accepted');
$broken(fn()=>['rows'=>[],'notice'=>['text'=>'x','tone'=>'loud']],'An unknown notice tone accepted');
foreach([fn()=>new ProviderResource('x','host',[new Field('secret','Secret',secret:true)],fn()=>[]),fn()=>new ProviderResource('x','host',[new Field('name','Name',column:['editable'=>true])],fn()=>[]),
    fn()=>new ProviderResource('x','bad key',[],fn()=>[]),fn()=>new ProviderResource('x','host',[new Field('id','Id')],fn()=>[]),fn()=>new ProviderResource('x','host',[new Field('revision','Revision')],fn()=>[]),fn()=>new ProviderResource('x','host',[new Field('name','Name')],fn()=>[],search:['missing'])] as $declare)
    try{$declare();$r=new Registry();$declare()->register($r,'X');verify(false,'An invalid provider declaration accepted');}catch(InvalidArgumentException){}
echo "61ade provider list parity, records, live, ACL, validation and developer-error contracts passed.\n";
